"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from agent_buyer_protection.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_over_cap_order_is_blocked_with_refund(self):
        out = self.run_cli(["check", str(EX / "order-check.json")])
        self.assertEqual(out["decision"], "block")
        self.assertEqual(out["refund_if_claimed"], 29.0)
        self.assertEqual(out["claim_path"], "cancel")

    def test_matching_order_is_allowed(self):
        req = json.loads((EX / "order-check.json").read_text(encoding="utf-8"))
        req["order"]["unit_price"] = 99
        self.assertEqual(self.run_cli(["check", self.write(req)])["decision"], "allow")


if __name__ == "__main__":
    unittest.main()
